import json
import os
from datetime import datetime
from typing import List, Dict, Optional
from fastapi import Depends, FastAPI, HTTPException, Path, status
from pydantic import BaseModel

app = FastAPI()

# Agent model
class BenchmarkData(BaseModel):
    latency: int
    accuracy: float

class AgentModel(BaseModel):
    id: str
    model: str
    version: str
    gpu: str
    cost_per_call: float
    benchmarks: BenchmarkData
    status: str = "enabled"
    fallback_chain: List[str] = []
    performance_history: List[BenchmarkData] = []
    cost_history: List[Dict[str, float]] = []

    class Config:
        orm_mode = True

# Agent registry in memory
REGISTRY_PATH = "memory/agents.json"
agents: Dict[str, AgentModel] = {}

def load_agents():
    global agents
    if not os.path.exists(REGISTRY_PATH):
        os.makedirs(os.path.dirname(REGISTRY_PATH), exist_ok=True)
        with open(REGISTRY_PATH, "w") as f:
            json.dump([], f)
    with open(REGISTRY_PATH, "r") as f:
        agent_data = json.load(f)
    for agent in agent_data:
        agents[agent["id"]] = AgentModel(**agent)

def save_agents():
    with open(REGISTRY_PATH, "w") as f:
        json.dump([agent.dict() for agent in agents.values()], f, indent=2)

# Initialize registry
load_agents()

# Helper to get agent by ID
def get_agent(agent_id: str) -> AgentModel:
    if agent_id not in agents:
        raise HTTPException(status_code=404, detail="Agent not found")
    return agents[agent_id]

# Endpoints
@app.get("/api/agents", response_model=List[AgentModel])
def list_agents():
    return list(agents.values())

@app.get("/api/agents/{agent_id}", response_model=AgentModel)
def get_agent_endpoint(agent_id: str):
    return get_agent(agent_id)

@app.post("/api/agents/{agent_id}/test", response_model=BenchmarkData)
def test_agent(agent_id: str):
    agent = get_agent(agent_id)
    # Simulated benchmark test
    simulated_latency = 180  # Simulated value
    simulated_accuracy = 0.92  # Simulated value
    benchmark_data = BenchmarkData(latency=simulated_latency, accuracy=simulated_accuracy)
    agent.performance_history.append(benchmark_data)
    save_agents()
    return benchmark_data

@app.post("/api/agents/{agent_id}/enable")
def enable_agent(agent_id: str):
    agent = get_agent(agent_id)
    if agent.status == "enabled":
        return {"message": "Agent already enabled"}
    agent.status = "enabled"
    save_agents()
    return {"message": "Agent enabled"}

@app.post("/api/agents/{agent_id}/disable")
def disable_agent(agent_id: str):
    agent = get_agent(agent_id)
    if agent.status == "disabled":
        return {"message": "Agent already disabled"}
    agent.status = "disabled"
    save_agents()
    return {"message": "Agent disabled"}

@app.post("/api/agents/{agent_id}/update-model")
def update_agent_model(agent_id: str, model: str, version: str, gpu: str, cost_per_call: float):
    agent = get_agent(agent_id)
    agent.model = model
    agent.version = version
    agent.gpu = gpu
    agent.cost_per_call = cost_per_call
    save_agents()
    return {"message": "Agent model updated"}

@app.get("/api/agents/{agent_id}/performance", response_model=List[BenchmarkData])
def get_agent_performance(agent_id: str):
    agent = get_agent(agent_id)
    return agent.performance_history

@app.get("/api/agents/{agent_id}/cost", response_model=List[Dict[str, float]])
def get_agent_cost(agent_id: str):
    agent = get_agent(agent_id)
    return agent.cost_history

# Run the app
if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
